package com.stockly.product.api.dto;

import com.stockly.product.domain.Product;
import org.mapstruct.BeanMapping;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingTarget;
import org.mapstruct.NullValuePropertyMappingStrategy;
import org.mapstruct.ReportingPolicy;

/**
 * MapStruct mapper between {@link Product} (entity) and the
 * {@code com.stockly.product.api.dto.*} records.
 *
 * <p>Generated by MapStruct at compile time ({@code mvn compile}). Spring
 * component model {@code spring} means the implementation is auto-registered
 * as a {@code @Component} and discovered by
 * {@code @Autowired}/{@code constructor injection}.
 *
 * <h2>Strategies</h2>
 * <ul>
 *   <li><b>Entity → Response ({@link #toResponse}):</b> straight field
 *       mapping. No nullability handling — all fields are present in the
 *       entity after a save.</li>
 *   <li><b>Create request → Entity ({@link #toEntity}):</b> ignores
 *       server-managed fields ({@code id}, {@code createdAt}, {@code updatedAt},
 *       {@code version}). {@code active} is set to {@code true} by the field
 *       default on {@link Product}.</li>
 *   <li><b>Update request → Entity ({@link #updateEntity}):</b>
 *       <em>partial update</em>. Uses
 *       {@link NullValuePropertyMappingStrategy#IGNORE} so a {@code null}
 *       in the request leaves the entity field untouched. The cross-field
 *       "at least one field" check lives on
 *       {@link UpdateProductRequest#hasAtLeastOneField()} so the service
 *       layer doesn't issue a no-op update.</li>
 * </ul>
 *
 * <h2>Reporting policy</h2>
 * <p>{@link ReportingPolicy#IGNORE} silences MapStruct warnings about
 * unmapped target fields when the field is ignored explicitly (e.g.
 * {@code id}, {@code version}). Without this the build log would be
 * noisy and the warnings would mask real issues.
 *
 * @since 0.1.0
 * @author Juan Nicolas Urrutia Salcedo — Universidad Surcolombiana de Neiva (Materia Inteligencia Artificial)
 */
@Mapper(
    componentModel = "spring",
    nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE,
    unmappedTargetPolicy = ReportingPolicy.IGNORE
)
public interface ProductMapper {

    /**
     * Entity → Response.
     *
     * @param product the source entity (must not be {@code null})
     * @return the response record
     */
    ProductResponse toResponse(Product product);

    /**
     * Create request → new Entity (not yet persisted).
     *
     * <p>Server-managed fields are ignored so the persistence layer assigns
     * them. {@code active} defaults to {@code true} via the entity's field
     * initializer.
     *
     * @param request the create request (must not be {@code null})
     * @return a new {@link Product} ready to be saved
     */
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    @Mapping(target = "version", ignore = true)
    Product toEntity(CreateProductRequest request);

    /**
     * Partial update: copy non-null fields from the request onto an existing
     * managed entity. {@code null} in the request means "no change".
     *
     * <p>The auditing listeners ({@code createdAt}, {@code updatedAt},
     * {@code version}) are managed by JPA and not touched by this method.
     *
     * @param target  the managed entity to update (must not be {@code null})
     * @param request the partial update request (must not be {@code null})
     */
    @BeanMapping(nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE)
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "sku", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    @Mapping(target = "version", ignore = true)
    void updateEntity(@MappingTarget Product target, UpdateProductRequest request);
}